import {useCallback,useEffect,useRef,useState} from 'react'
import type {FormEvent} from 'react'
import {Activity,ArrowLeft,ArrowUpRight,Archive,Boxes,ChevronRight,FileText,GitBranch,LayoutDashboard,LockKeyhole,Network,LogOut,Play,Plus,RefreshCw,Search,Server,Shield,Users} from 'lucide-react'
import {api,APIError,bytes,label,post,setCSRF,short,time,getDisplayTimeZone,setDisplayTimeZone} from './api'
import type {Action,Audit,Details,Operation,OperationEvent,Preview,Role,Service,Session,Submit,User} from './api'
import {Badge,Button,Empty,Modal,Notice} from './ui'
import {createOperationKey} from './operationKey'
import MetricsView,{HostMetricsView} from './Metrics'
import RegistrationDialog from './Registration'
import GitSourceView from './GitSource'
import LogViewer from './LogViewer'
import FilesDiff from './FilesDiff'
import ReleaseEvidenceView from './ReleaseEvidence'
import OperationDiagnostics from './OperationDiagnostics'
import HealthChecks from './HealthChecks'
import StorageView from './StorageView'
import TrafficView from './Traffic'
import ProxyWafView from './ProxyWaf'

const terminalStates=['succeeded','failed','cancelled']
const tone=(state:string):'good'|'bad'|'warn'|'neutral'=>['succeeded','healthy','running'].includes(state)?'good':['failed','unhealthy','requires_recovery'].includes(state)?'bad':['queued','interrupted','stale'].includes(state)?'warn':'neutral'
const errorMessage=(error:unknown)=>error instanceof Error?error.message:'Не удалось выполнить запрос'

export default function App(){
  const [session,setSession]=useState<Session|null>(null)
  const sessionRef=useRef<Session|null>(null)
  sessionRef.current=session
  const [loading,setLoading]=useState(true)
  const [expired,setExpired]=useState(false)
  useEffect(()=>{api<Session>('/api/auth/session').then(value=>{sessionRef.current=value;setCSRF(value.csrf_token);setSession(value)}).catch(()=>{}).finally(()=>setLoading(false));const expire=()=>{sessionRef.current=null;setSession(null);setCSRF('');setExpired(true)};window.addEventListener('auth-expired',expire);return()=>window.removeEventListener('auth-expired',expire)},[])
  useEffect(()=>{
    const userID=session?.user.id
    if(!userID)return
    let active=true,timer:ReturnType<typeof setTimeout>|undefined
    const controller=new AbortController()
    const refreshSession=async()=>{
      try{
        const value=await api<Session>('/api/auth/session',{signal:controller.signal})
        if(active&&sessionRef.current?.user.id===userID){
          if(value.user.id!==userID){sessionRef.current=null;setCSRF('');setSession(null);setExpired(true)}
          else{sessionRef.current=value;setCSRF(value.csrf_token);setSession(value)}
        }
      }catch(error){
        if(active&&sessionRef.current?.user.id===userID&&error instanceof APIError&&[401,403].includes(error.status)){sessionRef.current=null;setCSRF('');setSession(null);setExpired(true)}
      }finally{if(active)timer=setTimeout(()=>void refreshSession(),5000)}
    }
    timer=setTimeout(()=>void refreshSession(),5000)
    return()=>{active=false;clearTimeout(timer);controller.abort()}
  },[session?.user.id])
  if(loading)return <div className="boot"><Boxes size={30}/><span>CTF Service Manager</span><small>Подключение к панели…</small></div>
  if(!session)return <Login expired={expired} onLogin={value=>{sessionRef.current=value;setCSRF(value.csrf_token);setSession(value);setExpired(false)}}/>
  return <Workspace user={session.user} onLogout={async()=>{await post('/api/auth/logout',{});sessionRef.current=null;setSession(null);setCSRF('')}}/>
}

function Login({expired,onLogin}:{expired:boolean;onLogin:(session:Session)=>void}){
  const [username,setUsername]=useState(''),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('')
  const submit=async(event:FormEvent)=>{event.preventDefault();setBusy(true);setError('');try{onLogin(await post<Session>('/api/auth/login',{username,password}))}catch(error){setError(errorMessage(error));setPassword('')}finally{setBusy(false)}}
  return <div className="login-shell"><div className="login-brand"><div className="brand-mark"><Boxes size={25}/></div><span>CTF SERVICE MANAGER</span></div><form className="login-card" onSubmit={submit}>
    <div className="login-icon"><LockKeyhole size={23}/></div><h1>Вход в командную панель</h1><p>Сервисы, релизы и восстановление вашей vulnbox.</p>
    {expired&&<Notice>Сессия завершена. Войдите снова.</Notice>}{error&&<Notice variant="error">{error}</Notice>}
    <label>Имя пользователя<input autoComplete="username" autoFocus required value={username} onChange={e=>setUsername(e.target.value)} placeholder="defender"/></label>
    <label>Пароль<input type="password" autoComplete="current-password" required value={password} onChange={e=>setPassword(e.target.value)}/></label>
    <Button busy={busy} type="submit" className="full">Войти <ChevronRight size={16}/></Button>
    <small>Первый администратор создаётся локально через <code>init-admin</code>.</small>
  </form><div className="login-footer"><Shield size={14}/> Локальный доступ команды · серверные сессии</div></div>
}

function Workspace({user,onLogout}:{user:User;onLogout:()=>Promise<void>}){
  const [displayZone,setDisplayZone]=useState(getDisplayTimeZone)
  const [page,setPage]=useState('dashboard'),[services,setServices]=useState<Service[]>([]),[details,setDetails]=useState<Record<string,Details>>({}),[operations,setOperations]=useState<Operation[]>([])
  const [selected,setSelected]=useState(''),[tab,setTab]=useState('overview'),[search,setSearch]=useState('')
  const [executor,setExecutor]=useState('unknown'),[error,setError]=useState(''),[updated,setUpdated]=useState<Date|null>(null),[refreshing,setRefreshing]=useState(false),[streamLive,setStreamLive]=useState(false)
  const [action,setAction]=useState<Action|null>(null),[operation,setOperation]=useState<Operation|null>(null)
  const [recoveryOperation,setRecoveryOperation]=useState(''),[selectedSnapshot,setSelectedSnapshot]=useState(''),[registering,setRegistering]=useState(false)
  const inFlight=useRef(false)
  const refresh=useCallback(async()=>{
    if(inFlight.current)return;inFlight.current=true;setRefreshing(true)
    try{
      const [list,jobs,status]=await Promise.all([api<Service[]>('/api/services'),api<Operation[]>('/api/operations'),api<{executor:string}>('/api/status')])
      setServices(list);setOperations(jobs);setExecutor(status.executor)
      const results=await Promise.allSettled(list.map(service=>api<Details>(`/api/services/${service.id}`)))
      const next:Record<string,Details>={};let unavailable=0
      results.forEach((result,index)=>{if(result.status==='fulfilled')next[list[index].id]=result.value;else unavailable++})
      setDetails(next);setError(unavailable?`Не удалось получить состояние ${unavailable} сервисов. Действия для них недоступны.`:'');setUpdated(new Date())
    }catch(error){setError(error instanceof APIError&&error.code==='executor_unavailable'?'':errorMessage(error));setExecutor('unavailable')}finally{inFlight.current=false;setRefreshing(false)}
  },[])
  useEffect(()=>{void refresh();const interval=setInterval(()=>void refresh(),5000);return()=>clearInterval(interval)},[refresh])
  useEffect(()=>{
    let socket:WebSocket|undefined,closed=false,retry:ReturnType<typeof setTimeout>|undefined
    const connect=()=>{
      const query=new URLSearchParams()
      socket=new WebSocket(`${location.protocol==='https:'?'wss':'ws'}://${location.host}/api/stream${query.size?'?'+query:''}`)
      socket.onopen=()=>setStreamLive(true)
      socket.onmessage=event=>{try{const value=JSON.parse(event.data) as {operations?:Operation[];executor?:string};if(value.operations)setOperations(value.operations);if(value.executor)setExecutor(value.executor)}catch{setStreamLive(false)}}
      socket.onclose=()=>{setStreamLive(false);if(!closed)retry=setTimeout(connect,5000)}
    };connect();return()=>{closed=true;clearTimeout(retry);socket?.close()}
  },[])
  const openService=(service:Service)=>{setSelected(service.id);setPage('dashboard');setTab('overview')}
  const current=details[selected]
  const active=operations.filter(job=>!terminalStates.includes(job.state))
  const failed=operations.filter(job=>['failed','requires_recovery'].includes(job.state))
  const running=Object.values(details).flatMap(value=>value.containers||[]).filter(value=>value.state==='running').length
  const containers=Object.values(details).reduce((n,value)=>n+(value.containers||[]).length,0)
  return <div className="app-shell"><aside className="sidebar">
    <a className="brand" href="/" onClick={event=>{event.preventDefault();setSelected('');setPage('dashboard')}}><div className="brand-mark"><Boxes size={23}/></div><div>CTF Manager<span>TEAM WORKSPACE</span></div></a>
    <div className="sidebar-section">УПРАВЛЕНИЕ</div><nav>
      <button className={page==='dashboard'?'nav-active':''} onClick={()=>{setPage('dashboard');setSelected('')}}><LayoutDashboard size={18}/>Обзор</button>
      <button className={page==='operations'?'nav-active':''} onClick={()=>{setPage('operations');setSelected('')}}><Activity size={18}/>Операции{active.length>0&&<span className="nav-count">{active.length}</span>}</button>
      <button className={page==='host-metrics'?'nav-active':''} onClick={()=>{setPage('host-metrics');setSelected('')}}><Server size={18}/>Метрики хоста</button>
      <button className={page==='storage'?'nav-active':''} onClick={()=>{setPage('storage');setSelected('')}}><Archive size={18}/>Хранилище панели</button>
      <button className={page==='traffic'?'nav-active':''} onClick={()=>{setPage('traffic');setSelected('')}}><Network size={18}/>Трафик</button>
      <button className={page==='proxy-waf'?'nav-active':''} onClick={()=>{setPage('proxy-waf');setSelected('')}}><Shield size={18}/>Proxy / WAF</button>
      {user.role==='admin'&&<><button className={page==='users'?'nav-active':''} onClick={()=>{setPage('users');setSelected('')}}><Users size={18}/>Команда</button><button className={page==='audit'?'nav-active':''} onClick={()=>{setPage('audit');setSelected('')}}><Shield size={18}/>Аудит</button></>}
    </nav><div className="sidebar-section service-heading">СЕРВИСЫ <span>{services.length}</span></div><nav className="service-nav">{services.map(service=><button key={service.id} className={selected===service.id?'nav-active':''} onClick={()=>openService(service)}><span className={`service-dot ${details[service.id]?.containers?.some(value=>value.state==='running')?'dot-live':''}`}/><span className="truncate">{service.name}</span></button>)}</nav>
    <div className="sidebar-bottom"><div className="host-line"><Server size={16}/><span>Локальная vulnbox</span><span className={`service-dot ${executor==='ok'?'dot-live':''}`}/></div><div className="user-line"><div className="avatar">{user.username.slice(0,2).toUpperCase()}</div><div className="user-name">{user.username}<small>{label(user.role)}</small></div><Button variant="ghost" title="Выйти" aria-label="Выйти" onClick={()=>void onLogout().catch(error=>setError(errorMessage(error)))}><LogOut size={16}/></Button></div></div>
  </aside><div className="workspace"><header className="topbar"><div className="breadcrumb">Рабочее пространство <ChevronRight size={14}/><span>{selected?services.find(service=>service.id===selected)?.name:page==='users'?'Команда':page==='audit'?'Аудит':page==='operations'?'Операции':page==='host-metrics'?'Метрики хоста':page==='storage'?'Хранилище панели':page==='traffic'?'Трафик':page==='proxy-waf'?'Proxy / WAF':'Обзор'}</span></div><div className="topbar-status"><span className={`service-dot ${streamLive?'dot-live':''}`}/>{streamLive?'Live':'Опрос каждые 5 с'}<span className="separator"/><select aria-label="Часовой пояс" value={displayZone} onChange={event=>{const value=event.target.value==='UTC'?'UTC':'browser';setDisplayTimeZone(value);setDisplayZone(value)}}><option value="browser">Время браузера</option><option value="UTC">UTC</option></select><Shield size={14}/>{label(user.role)}</div></header>
  <main>{error&&<Notice variant="error">{error}</Notice>}{executor!=='ok'&&<Notice variant="warning">Executor {executor==='unknown'?'ещё не проверен':'недоступен'}. Состояние сервисов требует обновления.</Notice>}
  {page==='traffic'?<TrafficView key={`${user.id}:${user.role}:${user.sensitive_access}`} services={services} user={user}/>:page==='proxy-waf'?<ProxyWafView key={`${user.id}:${user.role}:${user.sensitive_access}`} services={services} user={user}/>:page==='storage'?<><PageTitle title="Хранилище панели" subtitle="Квоты, используемое место и защищённые артефакты."/><StorageView/></>:page==='users'?<Team currentUser={user}/>:page==='audit'?<AuditView/>:page==='host-metrics'?<><PageTitle title="Метрики хоста" subtitle="CPU, память, сеть и хранилища машины Docker Engine."/><HostMetricsView/></>:page==='operations'?<><PageTitle title="Операции" subtitle="Очередь, этапы выполнения и сохранённые результаты."/><Operations operations={operations} services={services} onSelect={setOperation}/></>:selected?<>
    <button className="back-link" onClick={()=>setSelected('')}><ArrowLeft size={15}/>Все сервисы</button>
    <PageTitle title={services.find(service=>service.id===selected)?.name||selected} subtitle={current?.service.description||'Управление зарегистрированным Compose-проектом.'} action={<Button variant="outline" busy={refreshing} onClick={()=>void refresh()}><RefreshCw size={15}/>Обновить</Button>}/>
    {!current?<Empty icon={<Server/>}>Состояние сервиса недоступно. Обновите данные после подключения executor.</Empty>:<>
      <div className="service-toolbar"><div className="toolbar-primary">{(['prepare','build','deploy','rollback'] as Action[]).map(value=><Button key={value} variant={value==='deploy'?'default':'outline'} disabled={user.role==='viewer'||!current.capabilities?.[value]} title={!current.capabilities?.[value]?'Операция недоступна в текущем состоянии':value==='prepare'?'Создать кандидат из локальной рабочей папки':label(value)} onClick={()=>setAction(value)}>{value==='deploy'?<Play size={14}/>:value==='prepare'?<GitBranch size={14}/>:value==='rollback'?<RefreshCw size={14}/>:<Boxes size={14}/>} {label(value)}</Button>)}
        {user.role==='admin'&&current.capabilities?.prepare_compose!==undefined&&<Button variant="outline" disabled={!current.capabilities.prepare_compose} title={current.capabilities.prepare_compose?'Проверить изменения Compose и собрать релиз':'Смена Compose недоступна в текущем состоянии'} onClick={()=>setAction('prepare_compose')}><FileText size={14}/>Сменить Compose</Button>}
      </div><div className="toolbar-secondary">{(['snapshot','start','stop','restart'] as Action[]).map(value=><Button key={value} variant="ghost" disabled={user.role==='viewer'||!current.capabilities?.[value]} onClick={()=>setAction(value)}>{label(value)}</Button>)}</div></div>
      <div className="tabs" role="tablist" aria-label="Разделы сервиса">{[['overview','Состояние'],['releases','Релизы'],['files','Файлы / Diff'],['checks','Проверки'],['snapshots','Снимки'],['logs','Логи'],['operations','Операции'],['metrics','Метрики'],['source','Источник Git'],['settings','Конфигурация']].map(([id,name])=><button key={id} role="tab" aria-selected={tab===id} className={tab===id?'tab-active':''} onClick={()=>setTab(id)}>{name}{id==='releases'&&<span>{current.releases?.length||0}</span>}</button>)}</div>
      {tab==='overview'&&<ServiceOverview details={current}/>}
      {tab==='releases'&&<Releases details={current}/>}
      {tab==='snapshots'&&<Snapshots details={current} canRestore={user.role!=='viewer'&&!!current.capabilities?.prepare} onRestore={id=>{setSelectedSnapshot(id);setAction('restore_snapshot')}}/>}
      {tab==='files'&&<FilesDiff key={selected} details={current} sensitiveAccess={user.sensitive_access}/>}
      {tab==='checks'&&<HealthChecks key={selected} serviceID={selected} role={user.role} canConfirm={user.role!=='viewer'} onUpdated={()=>void refresh()}/>}
      {tab==='settings'&&<Configuration details={current}/> }
      {tab==='source'&&<GitSourceView key={selected} serviceID={selected} candidateID={current.candidate_id} role={user.role} initialized={!!current.capabilities?.prepare} canFetch={user.role!=='viewer'&&!!current.capabilities?.fetch_source} onFetch={()=>setAction('fetch_source')}/>}
      {tab==='metrics'&&<MetricsView serviceID={selected}/>}
      {tab==='operations'&&<Operations operations={operations.filter(job=>job.spec.service_id===selected)} services={services} onSelect={setOperation}/>}
      {tab==='logs'&&<LogViewer key={selected} details={current} sensitiveAccess={user.sensitive_access}/>}
    </>}
  </>:<>
    <PageTitle title="Обзор сервисов" subtitle="Состояние vulnbox и операции вашей команды." action={<div className="page-actions"><Button variant="outline" busy={refreshing} onClick={()=>void refresh()}><RefreshCw size={15}/>Обновить</Button>{user.role==='admin'&&<Button disabled={executor!=='ok'} onClick={()=>setRegistering(true)}><Plus size={15}/>Добавить сервис</Button>}</div>}/>
    <div className="summary-grid"><Summary icon={<Boxes size={18}/>} title="Сервисы" value={updated?String(services.length):'—'} detail="зарегистрировано"/><Summary icon={<Server size={18}/>} title="Контейнеры" value={updated?`${running} / ${containers}`:'—'} detail="запущено · не оценка checker"/><Summary icon={<Activity size={18}/>} title="Активные операции" value={updated?String(active.length):'—'} detail="очередь и выполнение"/><Summary icon={<Shield size={18}/>} title="Ошибки в журнале" value={updated?String(failed.length):'—'} detail="в загруженной истории" warn={failed.length>0}/></div>
    <div className="section-title"><div><h2>Сервисы <span className="count">{services.length}</span></h2><p>{updated?`Обновлено ${updated.toLocaleTimeString('ru-RU')}`:'Получаем состояние executor'}</p></div><div className="search"><Search size={16}/><input aria-label="Поиск сервисов" placeholder="Найти сервис…" value={search} onChange={event=>setSearch(event.target.value)}/></div></div>
    {services.length===0?<Empty icon={<Boxes size={30}/>}><strong>{updated?'Сервисы ещё не зарегистрированы':'Реестр сервисов пока недоступен'}</strong><span>{updated?(user.role==='admin'?'Добавьте существующий Compose-проект, указав путь к сервису.':'Зарегистрировать сервис через панель может Admin.'):'После подключения executor здесь появится состояние зарегистрированных сервисов.'}</span>{updated&&user.role==='admin'&&<Button disabled={executor!=='ok'} onClick={()=>setRegistering(true)}><Plus size={15}/>Добавить сервис</Button>}</Empty>:<div className="service-grid">{services.filter(service=>service.name.toLowerCase().includes(search.toLowerCase())).map(service=><ServiceCard key={service.id} service={service} details={details[service.id]} busy={active.find(job=>job.spec.service_id===service.id)} onOpen={()=>openService(service)}/>)}</div>}
    <div className="section-title operations-heading"><div><h2>Последние операции</h2><p>Результаты сохраняются после закрытия вкладки.</p></div><Button variant="ghost" onClick={()=>setPage('operations')}>Вся история<ArrowUpRight size={15}/></Button></div><Operations operations={operations.slice(0,6)} services={services} onSelect={setOperation}/>
  </>}
  <footer className="footer"><span>CTF Service Manager <Badge>MVP</Badge></span><span>{displayZone==='UTC'?'Время UTC':'Локальное время браузера'} · точный UTC доступен во всплывающих датах</span></footer>
  </main></div>
  {registering&&<RegistrationDialog onClose={()=>setRegistering(false)} onRegistered={(service,sourceTab)=>{setRegistering(false);setServices(value=>value.some(item=>item.id===service.id)?value:[...value,service]);openService(service);if(sourceTab)setTab('source');void refresh()}}/>}
  {action&&current&&<ActionDialog action={action} details={current} user={user} recoveryOperation={recoveryOperation} snapshotID={selectedSnapshot} onClose={()=>{setAction(null);setRecoveryOperation('');setSelectedSnapshot('')}} onAccepted={operation=>{if(operation.spec.kind==='prepare_compose')setTab('releases');setOperation(operation);setAction(null);setRecoveryOperation('');setSelectedSnapshot('');void refresh()}}/>}
  {operation&&<OperationDialog operation={operations.find(value=>value.spec.id===operation.spec.id)||operation} sensitiveAccess={user.sensitive_access} canCancel={user.role!=='viewer'} onCancelled={()=>void refresh()} canRecover={user.role!=='viewer'&&!!details[operation.spec.service_id]?.capabilities?.recover} onRecover={()=>{setRecoveryOperation(operation.spec.id);setSelected(operation.spec.service_id);setPage('dashboard');setTab('operations');setOperation(null);setAction('recover')}} onClose={()=>setOperation(null)}/>}
  </div>
}

function PageTitle({title,subtitle,action}:{title:string;subtitle:string;action?:React.ReactNode}){return <div className="page-title"><div><h1>{title}</h1><p>{subtitle}</p></div>{action}</div>}
function Summary({icon,title,value,detail,warn}:{icon:React.ReactNode;title:string;value:string;detail:string;warn?:boolean}){return <div className="summary-card"><div className="summary-label">{title}{icon}</div><strong className={warn?'text-warning':''}>{value}</strong><small>{detail}</small></div>}
function ServiceCard({service,details,busy,onOpen}:{service:Service;details?:Details;busy?:Operation;onOpen:()=>void}){
  const running=details?.containers?.filter(value=>value.state==='running').length||0
  const health=details?.health?.find(value=>value.source==='local_functional')
  return <button className="service-card" onClick={onOpen}><div className="service-card-title"><div className="service-icon"><Boxes size={22}/></div><Badge tone={details?(running?'good':'neutral'):'warn'}>{details?`${running} / ${details.containers?.length||0} запущено`:'Нет данных'}</Badge></div><h3>{service.name}<ArrowUpRight size={16}/></h3><p>{service.description||`Compose · ${service.compose_project}`}</p><div className="service-facts"><div><span>Локальная проверка</span><span>{health?label(health.state):'Не настроена'}</span></div><div><span>Активный релиз</span><code>{short(details?.current_release_id)}</code></div><div><span>Компоненты</span><span>{service.targets.join(', ')}</span></div><div><span>Drift файлов</span><span>{details?.drift?.state==='changed'?'Есть изменения':details?.drift?.state==='unchanged'?'Нет':details?.drift?.state==='unverified'?'Непроверенная точка':'Неизвестно'}</span></div></div><div className="service-card-footer">{busy?<><Activity size={14}/>{label(busy.spec.kind)} · {label(busy.stage)}</>:<><span className="service-dot"/>Checker организаторов: неизвестно</>}<ChevronRight size={15}/></div></button>
}

function Operations({operations,services,onSelect}:{operations:Operation[];services:Service[];onSelect:(operation:Operation)=>void}){
  if(operations.length===0)return <Empty icon={<Activity size={25}/>}><strong>Операций пока нет</strong><span>Здесь появятся запросы команды и этапы их выполнения.</span></Empty>
  return <div className="table-wrap"><table><thead><tr><th>Операция</th><th>Сервис</th><th>Состояние</th><th>Этап</th><th>Создана</th><th/></tr></thead><tbody>{operations.map(operation=><tr key={operation.spec.id} onClick={()=>onSelect(operation)}><td><button className="table-link" onClick={event=>{event.stopPropagation();onSelect(operation)}}>{label(operation.spec.kind)}</button><small className="mono">{short(operation.spec.id)}</small></td><td>{services.find(service=>service.id===operation.spec.service_id)?.name||operation.spec.service_id}</td><td><Badge tone={tone(operation.state)}>{label(operation.state)}</Badge></td><td className="muted">{label(operation.stage)}{operation.state==='queued'&&operation.queue_wait&&<small>{label(operation.queue_wait.reason)}{operation.queue_wait.lane&&<span className="queue-blocker">{label(operation.queue_wait.lane)} · лимит {operation.queue_wait.limit}</span>}{operation.queue_wait.blockers.map(blocker=><span className="queue-blocker" key={`${blocker.resource}:${blocker.operation_id}`} title={`${blocker.resource} · ${blocker.operation_id} · ${blocker.actor}`}>{blocker.resource} · {short(blocker.operation_id)} · {blocker.actor}</span>)}</small>}</td><td className="muted nowrap" title={operation.created_at}>{time(operation.created_at)}</td><td><ChevronRight size={14}/></td></tr>)}</tbody></table></div>
}

function ServiceOverview({details}:{details:Details}){
  const health=details.health||[]
  return <div className="overview-grid"><div className="panel"><div className="panel-heading"><div><h2><Server size={17}/>Контейнеры</h2><p>Фактическое состояние Docker.</p></div><Badge>{details.observed_state}</Badge></div><div className="container-list">{(details.containers||[]).map(container=><div className="container-row" key={container.id}><div className="component-icon"><Boxes size={17}/></div><div className="container-name"><strong>{container.component}</strong><code>{short(container.id)}</code></div><div><Badge tone={container.state==='running'?'good':'neutral'}>{container.state}</Badge><small>{container.health||'healthcheck не настроен'}</small></div></div>)}{!details.containers?.length&&<Empty>Контейнеры не найдены.</Empty>}</div></div>
  <div className="panel"><div className="panel-heading"><div><h2><Shield size={17}/>Проверки доступности</h2><p>Каждый источник оценивается отдельно.</p></div></div><div className="health-list">{['docker_healthcheck','readiness','local_functional','manual','external_checker'].map(source=>{const value=health.find(item=>item.source===source);return <div key={source}><span>{label(source)}{value?.observed_at&&<small title={value.observed_at}>{time(value.observed_at)}</small>}{value?.reason&&<small>{value.reason}</small>}</span><Badge tone={tone(value?.state||'unknown')}>{label(value?.state||(source==='external_checker'?'unknown':'not_configured'))}</Badge></div>})}</div></div>
  <div className="panel span-two">{details.drift&&<Notice variant={details.drift.state==='changed'||details.drift.state==='unverified'?'warning':'info'}>Управляемые файлы: {details.drift.state==='changed'?'изменены вне активного релиза':details.drift.state==='unchanged'?'совпадают с записанным релизом':details.drift.state==='unverified'?'непроверенная точка возврата':'состояние неизвестно'}. {details.drift.reason}</Notice>}<div className="panel-heading"><div><h2><GitBranch size={17}/>Версии и политика</h2><p>Артефакты и подтверждённые границы управления.</p></div></div><div className="facts-grid"><Fact label="Текущий релиз" value={details.current_release_id||'Ещё не зафиксирован'}/><Fact label="Подготовленный кандидат" value={details.candidate_id||'Нет кандидата'}/><Fact label="Ревизия политики" value={String(details.service.policy_revision)}/><Fact label="Управляемые компоненты" value={details.service.targets.join(', ')}/></div>{!!details.component_versions?.length&&<div className="table-wrap"><table><thead><tr><th>Компонент</th><th>Фактический образ</th><th>Сверка с записанным релизом</th><th>Наблюдаемая версия</th></tr></thead><tbody>{details.component_versions.map(value=><tr key={value.component}><td>{value.component}</td><td><code title={value.image_id}>{short(value.image_id)}</code></td><td><Badge tone={value.state==='different_image'||value.state==='missing'||value.state==='image_matches_identity_changed'||value.state==='runtime_configuration_changed'||value.state==='runtime_configuration_unknown'?'warn':'neutral'}>{value.state==='matches_recorded_image'?'Образ совпадает':value.state==='runtime_configuration_changed'?'Конфигурация изменена':value.state==='runtime_configuration_unknown'?'Конфигурация неизвестна':value.state==='image_matches_identity_changed'?'Образ совпадает · новая идентичность':value.state==='different_image'?'Другой образ':value.state==='missing'?'Контейнер отсутствует':'Неизвестно'}</Badge></td><td><code>{value.observed_release_id||'Точный релиз неизвестен'}</code>{value.release_evidence&&<small>{value.release_evidence==='image_and_managed_bind_tree'?'Образ и файлы bind совпадают':value.release_evidence==='unique_image_match'?'Уникальное совпадение image ID':'Записанные контейнер и дерево совпадают'}</small>}{value.ambiguity_reason&&<small>{value.ambiguity_reason}</small>}{!value.observed_release_id&&value.possible_release_ids?.length>0&&<small>Возможные: {value.possible_release_ids.join(', ')}</small>}</td></tr>)}</tbody></table></div>}<p className="muted section-note">Совпадение образа не определяет точную версию файлов bind mounts или полный релиз.</p></div></div>
}
function Fact({label:heading,value}:{label:string;value:string}){return <div className="fact"><span>{heading}</span><code>{value}</code></div>}
function Releases({details}:{details:Details}){return <div className="panel"><div className="panel-heading"><div><h2><Archive size={17}/>Сохранённые релизы</h2><p>Точные локальные образы и версия управляемых файлов.</p></div></div>{details.releases?.length?<div className="release-list">{details.releases.map(release=><div key={release.id} className="release"><div className="release-header"><code>{release.id}</code>{release.id===details.current_release_id?<Badge tone="good">Активный</Badge>:<Badge>Сохранённый</Badge>}<span>{time(release.created_at)}</span></div><div className="release-meta"><span>Дерево <code>{short(release.tree_digest)}</code></span><span>Источник: {release.source}</span><span>Политика #{release.policy_revision}</span><span>Автор: <code>{release.author}</code></span></div>{release.git_source&&<div className="release-git"><span><GitBranch size={13}/>Git commit <code>{release.git_source.commit}</code></span><small>{release.git_source.url} · {release.git_source.ref}{release.git_source.subdirectory?` · ${release.git_source.subdirectory}`:''}</small></div>}{release.images?.map(image=><div className="image-row" key={image.component}><Boxes size={14}/>{image.component}<code>{image.image_id}</code></div>)}<ReleaseEvidenceView serviceID={details.service.id} releaseID={release.id}/></div>)}</div>:<Empty icon={<Archive/>}>Создайте исходный снимок, затем подготовьте и соберите кандидат.</Empty>}</div>}
function Snapshots({details,canRestore,onRestore}:{details:Details;canRestore:boolean;onRestore:(id:string)=>void}){return <div className="panel"><div className="panel-heading"><div><h2><Archive size={17}/>Снимки файлов</h2><p>Целостная копия управляемых файлов. Работоспособность приложения и согласованность БД этим не подтверждаются.</p></div></div>{details.snapshots?.length?<div className="table-wrap"><table><thead><tr><th>Идентификатор</th><th>Назначение</th><th>Git commit</th><th>Дерево</th><th>Размер</th><th>Создан</th><th/></tr></thead><tbody>{details.snapshots.map(snapshot=><tr key={snapshot.id}><td><code>{snapshot.id}</code></td><td><Badge>{snapshot.purpose==='manual'?'Ручной':label(snapshot.purpose)}</Badge></td><td><code title={snapshot.git_source?.commit}>{short(snapshot.git_source?.commit)}</code>{snapshot.git_source&&<small>{snapshot.git_source.ref}</small>}</td><td><code>{short(snapshot.tree_digest)}</code></td><td>{bytes(snapshot.bytes)}</td><td title={snapshot.created_at}>{time(snapshot.created_at)}</td><td><Button variant="outline" disabled={!canRestore} onClick={()=>onRestore(snapshot.id)}>Создать кандидат</Button></td></tr>)}</tbody></table></div>:<Empty>Снимков пока нет.</Empty>}</div>}
function Configuration({details}:{details:Details}){return <div className="panel"><div className="panel-heading"><div><h2><FileText size={17}/>Зарегистрированная конфигурация</h2><p>Настройки компонентов, управляемых файлов и игровых хранилищ, подтверждённые при регистрации.</p></div></div><div className="facts-grid"><Fact label="Compose project" value={details.service.compose_project}/><Fact label="Рабочий каталог" value={details.service.project_directory}/><Fact label="Исходный workspace" value={details.service.source_directory}/><Fact label="Управляемые файлы" value={details.service.managed_paths.map(value=>value.path).join(', ')}/></div><h3 className="inner-heading">Хранилища данных</h3>{details.service.data_paths?.length?<div className="table-wrap"><table><thead><tr><th>Хранилище</th><th>Тип</th><th>Компонент</th><th>Назначение</th><th>Значимые данные</th></tr></thead><tbody>{details.service.data_paths.map(value=><tr key={value.name}><td>{value.name}</td><td>{value.kind}</td><td>{value.component}</td><td><code>{value.target}</code></td><td>{value.significant?'Да':'Нет'}</td></tr>)}</tbody></table></div>:<Empty>Хранилища не зарегистрированы.</Empty>}</div>}

function ActionDialog({action,details,user,recoveryOperation,snapshotID,onClose,onAccepted}:{action:Action;details:Details;user:User;recoveryOperation?:string;snapshotID?:string;onClose:()=>void;onAccepted:(operation:Operation)=>void}){
  const codeBinds=details.service.data_paths?.filter(data=>data.allow_code_updates)||[]
  const options=(details.releases||[]).filter(value=>action!=='rollback'||value.id!==details.current_release_id).sort((a,b)=>Date.parse(b.created_at)-Date.parse(a.created_at))
  const [release,setRelease]=useState(options[0]?.id||''),[plan,setPlan]=useState<{request:string;preview:Preview}|null>(null),[busy,setBusy]=useState(false),[loading,setLoading]=useState(false),[error,setError]=useState(''),[confirmData,setConfirmData]=useState(false),[acceptDrift,setAcceptDrift]=useState(false)
  const [confirmCompose,setConfirmCompose]=useState(false)
  const [composeFromGit,setComposeFromGit]=useState(!!details.capabilities?.fetch_source)
  const preparingCompose=action==='prepare_compose'
  const getsGit=action==='fetch_source'||(preparingCompose&&composeFromGit)
  const selectsRelease=action==='deploy'||action==='rollback'
  const [key]=useState(createOperationKey)
  const request:Submit={service_id:details.service.id,action,idempotency_key:key,...(action==='build'?{candidate_id:details.candidate_id}:{}),...(action==='restore_snapshot'?{snapshot_id:snapshotID}:{}),...(acceptDrift?{accept_file_drift:true}:{}),...(selectsRelease?{release_id:release}:{}),...(action==='recover'?{recovery_operation_id:recoveryOperation}:{}),...(preparingCompose&&composeFromGit?{compose_from_git:true}:{})}
  const requestString=JSON.stringify(request)
  const preview=plan?.request===requestString?plan.preview:null
  const candidateCommit=action==='build'&&preview?.candidate_id
    ?details.snapshots?.find(snapshot=>snapshot.id===preview.candidate_id)?.git_source?.commit
    :undefined
  useEffect(()=>{let active=true;setPlan(null);setError('');setConfirmData(false);setConfirmCompose(false);setLoading(true);post<Preview>('/api/preview',JSON.parse(requestString)).then(result=>{if(active)setPlan({request:requestString,preview:result})}).catch(error=>{if(active)setError(errorMessage(error))}).finally(()=>{if(active)setLoading(false)});return()=>{active=false}},[requestString])
  const switchesCompose=selectsRelease&&!!preview?.compose_change
  const composeBlocked=switchesCompose&&(user.role!=='admin'||!confirmCompose)
  const submit=async()=>{if(!preview||composeBlocked)return;setBusy(true);setError('');try{onAccepted(await post<Operation>('/api/operations',{...request,plan_digest:preview.plan_digest,confirm_data_compatibility:confirmData,...(switchesCompose?{confirm_compose_change:true}:{})}))}catch(error){setError(errorMessage(error));if(error instanceof APIError&&error.status===409)setPlan(null)}finally{setBusy(false)}}
  const title=preparingCompose?'Сменить Compose':label(action)
  return <Modal open onClose={()=>{if(!busy)onClose()}} title={`${title} · ${details.service.name}`} description={preparingCompose?'Подготовьте релиз с новым Compose, пока сервис работает.':'План сформирован executor по зарегистрированной политике.'} wide><div className="dialog-body">
    {preparingCompose&&<>
      <label>Источник Compose<select disabled={busy} value={composeFromGit?'git':'workspace'} onChange={event=>setComposeFromGit(event.target.value==='git')}>
        <option value="git" disabled={!details.capabilities?.fetch_source}>Из Git</option><option value="workspace">Из рабочей папки</option>
      </select></label>
      <p className="section-note">Панель проверит изменения и соберёт новый релиз. В этом режиме можно менять лимиты CPU, памяти и числа процессов. Состав компонентов, порты, сети и монтирования сохраняются. Готовый релиз можно применить отдельно.</p>
    </>}
    {selectsRelease&&<label>Целевой релиз<select disabled={busy} value={release} onChange={event=>{setAcceptDrift(false);setRelease(event.target.value)}}>{options.map(value=><option key={value.id} value={value.id}>{value.id} · {time(value.created_at)}</option>)}</select></label>}
    {loading&&<div className="loading-line"><RefreshCw size={16} className="spin"/>Проверка файлов, образов и политики…</div>}{error&&<Notice variant="error">{error}</Notice>}
    {preview&&<>
      {action==='prepare'&&<Notice>«Подготовить» создаёт кандидат из локальной рабочей папки и выбирает его для следующей сборки. Для обновления из репозитория откройте «Источник Git» и нажмите «Получить из Git».</Notice>}
      {action==='restore_snapshot'&&<Notice>Снимок {snapshotID} станет новым неизменяемым кандидатом. Активный сервис и workspace не изменятся. Затем соберите и примените релиз.</Notice>}{action==='fetch_source'&&<Notice>Панель создаст кандидат из выбранной версии Git и сохранит утверждённые Compose-файлы сервера. Перед сборкой проверьте точный Git commit и изменения остальных управляемых файлов, включая Dockerfile.</Notice>}<div className="preview-facts"><Fact label="Компоненты" value={preview.targets.join(', ')}/><Fact label="Политика" value={`Ревизия ${preview.policy_revision}`}/><Fact label="Действующий релиз" value={preview.active_release_id||'Не зафиксирован'}/>{candidateCommit&&<Fact label="Git commit кандидата" value={candidateCommit}/>}<Fact label="Точка возврата" value={preview.has_rollback?'Исходная версия записана':'Не подтверждена'}/></div>
      {['stop','restart','deploy','rollback'].includes(action)&&<Notice variant="warning">Операция может прервать доступность компонентов: {preview.targets.join(', ')}.</Notice>}
      {getsGit&&preview.git_source&&<div className="preview-facts"><Fact label="Репозиторий" value={preview.git_source.url||'—'}/><Fact label="Ветка / тег / commit" value={preview.git_source.ref||'HEAD'}/></div>}
      {switchesCompose&&<ComposeChangeReview preview={preview} admin={user.role==='admin'} confirmed={confirmCompose} onConfirm={setConfirmCompose}/>}
      <div className="diff-heading"><h3>Изменения файлов</h3><Badge>{preview.changed_files?.length||0}</Badge></div>{getsGit?<p className="muted">Файлы будут проверены при получении исходников. Точный commit сохраняется вместе с кандидатом.</p>:!user.sensitive_access?<Notice>Детали diff скрыты. Доступ выдаёт администратор команды.</Notice>:preview.changed_files?.length?<div className="diff-list">{preview.changed_files.slice(0,150).map(value=><div key={value.path}><Badge tone={value.change==='deleted'?'bad':'neutral'}>{value.change}</Badge><code>{value.path}</code></div>)}{preview.changed_files.length>150&&<small>Показаны первые 150 файлов.</small>}</div>:<p className="muted">Изменений управляемых файлов в этом плане нет.</p>}
      {preview.images?.length? <div className="plan-images"><h3>Локальные образы</h3>{preview.images.map(value=><div key={value.component}><span>{value.component}</span><code>{short(value.image_id)}</code></div>)}</div>:null}
      {preview.active_file_drift&&<Notice variant="warning">Активные файлы изменены вне панели. Точка возврата будет содержать эти файлы без подтверждения работоспособности.{user.sensitive_access&&<ul>{preview.drift_changed_files?.map(file=><li key={file.path}><code>{file.path}</code> · {file.change}</li>)}</ul>}{user.sensitive_access?<label className="checkbox-label"><input type="checkbox" checked={acceptDrift} onChange={event=>setAcceptDrift(event.target.checked)}/><span>Принимаю показанные изменения как непроверенную точку возврата. Сформировать новый план с этим решением.</span></label>:<p>Для просмотра и принятия drift нужен доступ к файлам и diff.</p>}</Notice>}
      {['deploy','rollback','recover'].includes(action)&&<div><h3>Игровые хранилища</h3>{details.service.data_paths?.length?<ul>{details.service.data_paths.map(data=><li key={data.name}><code>{data.component}: {data.target}</code> · {data.kind} · {data.significant?'сохраняется отдельно от кода':data.loss_accepted?'потеря временных данных разрешена':'требует политики'}</li>)}</ul>:<p className="muted">Отдельные хранилища не зарегистрированы.</p>}</div>}
      {preview.space&&<div><h3>Оценка места</h3>{!preview.space.estimate_known&&<p className="muted">Размер получаемого Git-дерева заранее неизвестен; действуют ограниченные квоты экспорта.</p>}<div className="preview-facts"><Fact label="Снимок / staging" value={`${bytes(preview.space.snapshot_bytes)} / ${bytes(preview.space.staging_bytes)}`}/><Fact label="Временные файлы Apply" value={bytes(preview.space.apply_temporary_bytes)}/><Fact label="Резерв Docker" value={bytes(preview.space.docker_reserve_bytes)}/><Fact label="Доступно в state" value={preview.space.state_available_bytes===null?'Неизвестно':bytes(preview.space.state_available_bytes)}/><Fact label="Доступно inode" value={preview.space.state_available_inodes===null?'Неизвестно':String(preview.space.state_available_inodes)}/></div><p className="muted">Предварительная оценка. Квоты и запас места будут повторно проверены до изменения сервиса.</p></div>}
      {preview.health_settings&&<div className="preview-facts"><Fact label="Прогрев" value={`${preview.health_settings.warmup_seconds} с`}/><Fact label="Проверки" value={`${preview.health_settings.overall_timeout_seconds} с · до ${preview.health_settings.attempts} попыток`}/></div>}
      {preview.check_summaries?.length?<div><h3>Локальные проверки</h3>{preview.check_summaries.map(check=><p key={check.id}>{check.source} · {check.kind} · {check.targets.join(', ')} · запрос до {check.timeout_seconds} с</p>)}<p className="muted">Ревизия проверок {preview.health_check_revision}</p></div>:null}
      {codeBinds.length>0&&['deploy','rollback','recover'].includes(action)&&<Notice variant="warning">Для кодовых bind-каталогов разрешена возможная потеря данных внутри управляемых путей при замене файлов:<ul>{codeBinds.map(data=><li key={data.name}>{data.component}: <code>{data.source} → {data.target}</code></li>)}</ul></Notice>}
      {preview.data_compatibility_required&&<label className="checkbox-label"><input type="checkbox" checked={confirmData} onChange={event=>setConfirmData(event.target.checked)}/><span>Подтверждаю совместимость выбранного кода с текущими игровыми данными и схемой БД. {codeBinds.length?'Постоянные хранилища не откатываются; для кодовых bind действует разрешённая потеря данных.':'Откат данных не выполняется.'}</span></label>}
      <p className="plan-hash">План <code>{short(preview.plan_digest)}</code> · изменение файлов или политики потребует нового просмотра.</p>
    </>}
    </div><div className="dialog-footer"><Button variant="outline" disabled={busy} onClick={onClose}>Отмена</Button><Button variant={action==='stop'?'danger':'default'} busy={busy} disabled={!preview||loading||composeBlocked||(preview.data_compatibility_required&&!confirmData)||!!(preview.active_file_drift&&!preview.accepted_file_drift)} onClick={()=>void submit()}>{preparingCompose?'Подготовить и собрать':label(action)}</Button></div></Modal>
}

function ComposeChangeReview({preview,admin,confirmed,onConfirm}:{preview:Preview;admin:boolean;confirmed:boolean;onConfirm:(value:boolean)=>void}){
  const labels:Record<string,string>={cpus:'CPU',mem_limit:'Память',pids_limit:'Процессы'}
  const changes=preview.compose_changes||[]
  return <section>
    <h3>Смена Compose</h3>
    {changes.length>0&&<div className="table-wrap"><table><thead><tr><th>Компонент</th><th>Лимит</th><th>Сейчас</th><th>После применения</th></tr></thead><tbody>
      {changes.map(change=><tr key={`${change.component}:${change.setting}`}><td>{change.component}</td><td>{labels[change.setting]||change.setting}</td><td>{change.before||'—'}</td><td>{change.after||'—'}</td></tr>)}
    </tbody></table></div>}
    <p className="section-note">Панель остановит затронутые контейнеры и запустит их с выбранной конфигурацией. Порты и хранилища сохраняются.</p>
    {admin?<label className="checkbox-label"><input type="checkbox" checked={confirmed} onChange={event=>onConfirm(event.target.checked)}/><span>Подтверждаю смену Compose и временный перерыв в работе сервиса.</span></label>:<Notice variant="warning">Смену Compose подтверждает администратор.</Notice>}
  </section>
}

function OperationDialog({operation,sensitiveAccess,canRecover,canCancel,onCancelled,onRecover,onClose}:{operation:Operation;sensitiveAccess:boolean;canRecover:boolean;canCancel:boolean;onCancelled:()=>void;onRecover:()=>void;onClose:()=>void}){
  const [events,setEvents]=useState<OperationEvent[]>([]),[error,setError]=useState(''),[cancelling,setCancelling]=useState(false),[cancelAccepted,setCancelAccepted]=useState(false)
  useEffect(()=>{setCancelAccepted(false)},[operation.spec.id])
  useEffect(()=>{if(!sensitiveAccess)return;let active=true;const refresh=()=>api<OperationEvent[]>(`/api/operations/${operation.spec.id}/events`).then(value=>{if(active){setEvents(value||[]);setError('')}}).catch(error=>{if(active)setError(errorMessage(error))});void refresh();const timer=setInterval(()=>void refresh(),2000);return()=>{active=false;clearInterval(timer)}},[operation.spec.id,sensitiveAccess])
  const cancel=async()=>{setCancelling(true);setError('');try{await post(`/api/operations/${operation.spec.id}/cancel`,{});setCancelAccepted(true);onCancelled()}catch(error){setError(errorMessage(error))}finally{setCancelling(false)}}
  return <Modal open onClose={onClose} title={label(operation.spec.kind)} description={`Операция ${operation.spec.id}`} wide><div className="dialog-body"><div className="operation-state"><Badge tone={tone(operation.state)}>{label(operation.state)}</Badge><span>{label(operation.stage)}</span>{operation.state==='queued'&&operation.queue_wait&&<span>{label(operation.queue_wait.reason)}</span>}<span className="muted" title={operation.created_at}>{time(operation.created_at)}</span></div>{operation.state==='queued'&&operation.queue_wait&&<Notice>{label(operation.queue_wait.reason)}{operation.queue_wait.lane&&<p>{operation.queue_wait.lane==='build'?'Сборка':operation.queue_wait.lane==='copy'?'Копирование':'Переключение'} · лимит {operation.queue_wait.limit}</p>}{operation.queue_wait.blockers.length>0&&<ul>{operation.queue_wait.blockers.map(blocker=><li key={`${blocker.resource}:${blocker.operation_id}`}><code>{blocker.resource}</code> · операция <code>{blocker.operation_id}</code> · инициатор <code>{blocker.actor}</code></li>)}</ul>}</Notice>}{operation.outcome.reason&&<Notice variant={operation.state==='succeeded'?'info':'error'}>{operation.outcome.reason}</Notice>}{operation.spec.kind==='prepare_compose'&&operation.state==='succeeded'&&<Notice>Релиз собран. Нажмите «Применить» в карточке сервиса, чтобы проверить план переключения.</Notice>}{operation.recovery_point_id&&<Notice>Точка возврата: <code>{operation.recovery_point_id}</code></Notice>}{(operation.cancel_requested||cancelAccepted)&&<Notice variant="warning">Запрошена отмена на безопасной границе. После начала переключения для завершения может потребоваться явное восстановление.</Notice>}{!sensitiveAccess?<Notice>Журнал операции доступен по разрешению администратора.</Notice>:<>{error&&<Notice variant="error">{error}</Notice>}<div className="event-list">{events.map(event=><div key={event.sequence}><time title={event.at}>{time(event.at)}</time><Badge>{event.kind}</Badge><pre>{event.message}</pre></div>)}</div><OperationDiagnostics operationID={operation.spec.id}/></>}<p className="muted">Закрытие окна не отменяет операцию. Отмена не прерывает запись файлов или Docker-команду посреди шага.</p></div><div className="dialog-footer"><Button variant="outline" onClick={onClose}>Закрыть</Button>{canCancel&&['queued','running'].includes(operation.state)&&<Button variant="outline" busy={cancelling} disabled={operation.cancel_requested||cancelAccepted} onClick={()=>void cancel()}>Запросить отмену</Button>}{canRecover&&['interrupted','requires_recovery'].includes(operation.state)&&<Button onClick={onRecover}>Посмотреть план восстановления</Button>}</div></Modal>
}

function Team({currentUser}:{currentUser:User}){
  const [users,setUsers]=useState<User[]>([]),[error,setError]=useState(''),[creating,setCreating]=useState(false),[busy,setBusy]=useState(false)
  const [username,setUsername]=useState(''),[password,setPassword]=useState(''),[role,setRole]=useState<Role>('defender'),[sensitive,setSensitive]=useState(false)
  const refresh=useCallback(()=>api<User[]>('/api/users').then(setUsers).catch(error=>setError(errorMessage(error))),[])
  useEffect(()=>{void refresh()},[refresh])
  const change=async(user:User,value:unknown)=>{setBusy(true);setError('');try{await api(`/api/users/${user.id}`,{method:'PATCH',body:JSON.stringify(value)});await refresh()}catch(error){setError(errorMessage(error))}finally{setBusy(false)}}
  const create=async(event:FormEvent)=>{event.preventDefault();setBusy(true);setError('');try{await post('/api/users',{username,password,role,sensitive_access:sensitive});setPassword('');setUsername('');setCreating(false);await refresh()}catch(error){setError(errorMessage(error))}finally{setBusy(false)}}
  return <><PageTitle title="Команда" subtitle="Локальные учётные записи, роли и доступ к чувствительным данным." action={<Button onClick={()=>setCreating(true)}><Plus size={16}/>Добавить участника</Button>}/>{error&&<Notice variant="error">{error}</Notice>}<div className="table-wrap"><table><thead><tr><th>Участник</th><th>Роль</th><th>Логи и diff</th><th>Состояние</th><th>Сессии</th></tr></thead><tbody>{users.map(user=><tr key={user.id}><td><strong>{user.username}</strong>{user.id===currentUser.id&&<small>Вы</small>}</td><td><select aria-label={`Роль ${user.username}`} disabled={busy} value={user.role} onChange={event=>void change(user,{role:event.target.value})}><option value="admin">Admin</option><option value="defender">Defender</option><option value="viewer">Viewer</option></select></td><td><input type="checkbox" aria-label={`Логи и diff для ${user.username}`} disabled={busy||user.role==='admin'} checked={user.sensitive_access} onChange={event=>void change(user,{sensitive_access:event.target.checked})}/></td><td><Button variant="ghost" disabled={busy} onClick={()=>void change(user,{disabled:!user.disabled})}>{user.disabled?'Разблокировать':'Заблокировать'}</Button><Badge tone={user.disabled?'neutral':'good'}>{user.disabled?'Заблокирован':'Активен'}</Badge></td><td><Button variant="outline" disabled={busy} onClick={()=>void post(`/api/users/${user.id}/revoke-sessions`,{}).catch(error=>setError(errorMessage(error)))}>Отозвать</Button></td></tr>)}</tbody></table></div><p className="muted section-note">Изменение роли, пароля или доступа отзывает сессии пользователя. Последнего активного Admin нельзя заблокировать.</p>
  <Modal open={creating} onClose={()=>{if(!busy)setCreating(false)}} title="Добавить участника" description="Учётная запись будет создана только в этой панели."><form onSubmit={event=>void create(event)}><div className="dialog-body">{error&&<Notice variant="error">{error}</Notice>}<label>Имя пользователя<input autoComplete="off" required pattern="[a-z0-9][a-z0-9_.\-]{2,63}" value={username} onChange={event=>setUsername(event.target.value)} placeholder="defender"/></label><label>Пароль · минимум 12 символов<input type="password" required minLength={12} maxLength={1024} autoComplete="new-password" value={password} onChange={event=>setPassword(event.target.value)}/></label><label>Роль<select value={role} onChange={event=>setRole(event.target.value as Role)}><option value="defender">Defender · управление сервисами</option><option value="viewer">Viewer · просмотр состояния</option><option value="admin">Admin · полное управление панелью</option></select></label><label className="checkbox-label"><input type="checkbox" checked={sensitive||role==='admin'} disabled={role==='admin'} onChange={event=>setSensitive(event.target.checked)}/><span>Разрешить логи, diff и журналы операций. Они могут содержать игровые секреты.</span></label></div><div className="dialog-footer"><Button type="button" variant="outline" onClick={()=>setCreating(false)}>Отмена</Button><Button busy={busy} type="submit">Создать участника</Button></div></form></Modal>
  </>
}
function AuditView(){const[events,setEvents]=useState<Audit[]>([]),[error,setError]=useState('');useEffect(()=>{api<Audit[]>('/api/audit').then(setEvents).catch(error=>setError(errorMessage(error)))},[]);return <><PageTitle title="Аудит панели" subtitle="Последние 200 событий авторизации и действий команды."/>{error&&<Notice variant="error">{error}</Notice>}<div className="table-wrap"><table><thead><tr><th>Время</th><th>Действие</th><th>Пользователь</th><th>Цель</th><th>Результат</th></tr></thead><tbody>{events.map(event=><tr key={event.id}><td className="nowrap" title={event.at}>{time(event.at)}</td><td>{event.action}</td><td><code>{short(event.actor)}</code></td><td><code>{event.target||'—'}</code></td><td><Badge tone={event.result==='denied'?'bad':event.result==='succeeded'?'good':'neutral'}>{event.result}</Badge></td></tr>)}</tbody></table></div></>}
